namespace Donkeh.Cli;

/// <summary>Selects the project shape generated by <c>donkeh new project</c>.</summary>
internal enum ProjectKind
{
    /// <summary>A standalone application that opens a blank window.</summary>
    Application,

    /// <summary>
    /// A component library plus a console test container that renders every
    /// component in the library.
    /// </summary>
    Framework
}
